import { ok, fail } from './result.js';
import { getCustomer, TIER_DISCOUNTS, normalizeId } from './customers.js';
import { getProduct } from './catalogue.js';
import { nextInvoiceNumber } from './numbering.js';
import { isValidDate as validateDate, addDays } from './dates.js';
import { lineTotal, lineDiscount, lineVAT, invoiceTotals } from './totals.js';

// Re-export for backward compatibility
export { lineTotal, lineDiscount, lineVAT, invoiceTotals };

/**
 * Create a new invoice.
 * @param {{ customerId: string, issueDate: string, lines: Array<{ sku: string, qty: number }>, terms?: string }} invoice
 * @returns {{ ok: true, value: { customerId: string, issueDate: string, status: string, lines: Array, terms: string, dueDate: string } } | { ok: false, error: string }}
 */
export function createInvoice({ customerId, issueDate, lines, terms = 'NET30' }) {
  // Normalize customer ID
  const normalizedCustomerId = normalizeId(customerId);

  // Validate customer exists
  const customerResult = getCustomer(normalizedCustomerId);
  if (!customerResult.ok) {
    return fail('CUSTOMER_NOT_FOUND');
  }

  // Validate issueDate format and is a real date
  if (!validateDate(issueDate)) {
    return fail('DATE_INVALID');
  }

  // Validate and calculate dueDate based on terms
  let dueDate;
  if (terms === 'NET14') {
    dueDate = addDays(issueDate, 14);
  } else if (terms === 'NET30') {
    dueDate = addDays(issueDate, 30);
  } else if (terms === 'EOM') {
    // Due on last day of issue month
    const issueParts = issueDate.split('-');
    const year = parseInt(issueParts[0], 10);
    const month = parseInt(issueParts[1], 10);
    const lastDayOfMonth = new Date(Date.UTC(year, month, 0)).getUTCDate();
    dueDate = `${year}-${String(month).padStart(2, '0')}-${String(lastDayOfMonth).padStart(2, '0')}`;
  } else {
    return fail('TERMS_INVALID');
  }

  // Validate lines is not empty
  if (!Array.isArray(lines) || lines.length === 0) {
    return fail('NO_LINES');
  }

  // Validate and build invoice lines
  const customer = customerResult.value;
  const invoiceLines = [];
  for (const line of lines) {
    // Validate qty
    if (!Number.isInteger(line.qty) || line.qty <= 0) {
      return fail('QTY_INVALID');
    }

    // Validate discountPercent if provided
    if (line.discountPercent !== undefined) {
      if (typeof line.discountPercent !== 'number' || line.discountPercent < 0 || line.discountPercent > 100) {
        return fail('DISCOUNT_INVALID');
      }
    }

    // Validate SKU exists in catalogue
    const productResult = getProduct(line.sku);
    if (!productResult.ok) {
      return fail('UNKNOWN_SKU');
    }

    const product = productResult.value;
    const newLine = {
      sku: line.sku,
      name: product.name,
      qty: line.qty,
      unitPrice: product.unitPrice,
      vatRate: product.vatRate,
    };

    // Apply discountPercent: use provided value, or apply tier discount if not provided
    if (line.discountPercent !== undefined) {
      newLine.discountPercent = line.discountPercent;
    } else {
      const tierDiscount = TIER_DISCOUNTS[customer.tier];
      if (tierDiscount > 0) {
        newLine.discountPercent = tierDiscount;
      }
    }

    invoiceLines.push(newLine);
  }

  const invoice = {
    customerId: normalizedCustomerId,
    issueDate,
    status: 'draft',
    lines: invoiceLines,
    terms,
    dueDate,
  };

  return ok(invoice);
}

/**
 * Calculate the total for a single line (qty × unitPrice).
 * @param {{ qty: number, unitPrice: number }} line
 * @returns {{ ok: true, value: number } | { ok: false, error: string }}
 */
export function lineTotal(line) {
  if (!line || typeof line.qty !== 'number' || typeof line.unitPrice !== 'number') {
    return fail('LINE_INVALID');
  }
  return ok(roundCents(line.qty * line.unitPrice));
}

/**
 * Calculate the discount for a single line (lineTotal × discountPercent / 100).
 * @param {{ qty: number, unitPrice: number, discountPercent?: number }} line
 * @returns {{ ok: true, value: number } | { ok: false, error: string }}
 */
export function lineDiscount(line) {
  if (!line || typeof line.qty !== 'number' || typeof line.unitPrice !== 'number') {
    return fail('LINE_INVALID');
  }

  if (!line.discountPercent) {
    return ok(0);
  }

  const lineTotalResult = lineTotal(line);
  if (!lineTotalResult.ok) {
    return lineTotalResult;
  }

  const discount = roundCents((lineTotalResult.value * line.discountPercent) / 100);
  return ok(Math.max(0, discount));
}

/**
 * Calculate the VAT for a single line ((lineTotal - lineDiscount) × vatRate / 100).
 * @param {{ qty: number, unitPrice: number, vatRate: number, discountPercent?: number }} line
 * @returns {{ ok: true, value: number } | { ok: false, error: string }}
 */
export function lineVAT(line) {
  if (!line || typeof line.qty !== 'number' || typeof line.unitPrice !== 'number' || typeof line.vatRate !== 'number') {
    return fail('LINE_INVALID');
  }

  const lineTotalResult = lineTotal(line);
  if (!lineTotalResult.ok) {
    return lineTotalResult;
  }

  const lineDiscountResult = lineDiscount(line);
  if (!lineDiscountResult.ok) {
    return lineDiscountResult;
  }

  const taxableAmount = lineTotalResult.value - lineDiscountResult.value;
  const vat = roundCents((taxableAmount * line.vatRate) / 100);
  return ok(Math.max(0, vat));
}

/**
 * Calculate totals for an invoice.
 * @param {{ lines: Array<{ qty: number, unitPrice: number, vatRate: number, discountPercent?: number }>, voucher?: { code: string, amount: number } }} invoice
 * @returns {{ ok: true, value: { subtotal: number, discount: number, vat: number, voucher: number, total: number } } | { ok: false, error: string }}
 */
export function invoiceTotals(invoice) {
  if (!invoice || !Array.isArray(invoice.lines)) {
    return fail('INVOICE_INVALID');
  }

  let subtotal = 0;
  let totalDiscount = 0;
  let totalVAT = 0;
  for (const line of invoice.lines) {
    const lineTotalResult = lineTotal(line);
    if (!lineTotalResult.ok) {
      return fail('LINE_INVALID');
    }
    subtotal += lineTotalResult.value;

    const lineDiscountResult = lineDiscount(line);
    if (!lineDiscountResult.ok) {
      return fail('LINE_INVALID');
    }
    totalDiscount += lineDiscountResult.value;

    const lineVATResult = lineVAT(line);
    if (!lineVATResult.ok) {
      return fail('LINE_INVALID');
    }
    totalVAT += lineVATResult.value;
  }

  subtotal = roundCents(subtotal);
  totalDiscount = roundCents(totalDiscount);
  totalVAT = roundCents(totalVAT);
  const voucherAmount = invoice.voucher ? roundCents(invoice.voucher.amount) : 0;
  const total = Math.max(0, roundCents(subtotal - totalDiscount + totalVAT - voucherAmount));

  return ok({
    subtotal,
    discount: totalDiscount,
    vat: totalVAT,
    voucher: voucherAmount,
    total,
  });
}

/**
 * Add or increase a line on an invoice.
 * @param {{ status: string, lines: Array<{ sku: string, name: string, qty: number, unitPrice: number, vatRate: number, discountPercent?: number }> }} invoice
 * @param {{ sku: string, qty: number, discountPercent?: number }} line
 * @returns {{ ok: true, value: object } | { ok: false, error: string }}
 */
export function addLine(invoice, { sku, qty, discountPercent }) {
  // Check invoice status
  if (invoice.status !== 'draft') {
    return fail('NOT_DRAFT');
  }

  // Validate qty
  if (!Number.isInteger(qty) || qty <= 0) {
    return fail('QTY_INVALID');
  }

  // Validate discountPercent if provided
  if (discountPercent !== undefined) {
    if (typeof discountPercent !== 'number' || discountPercent < 0 || discountPercent > 100) {
      return fail('DISCOUNT_INVALID');
    }
  }

  // Validate SKU exists in catalogue
  const productResult = getProduct(sku);
  if (!productResult.ok) {
    return fail('UNKNOWN_SKU');
  }

  const product = productResult.value;
  const newLines = invoice.lines.map((line) => ({ ...line }));

  // Check if SKU already exists on invoice
  const existingLineIndex = newLines.findIndex((line) => line.sku === sku);
  if (existingLineIndex !== -1) {
    // Increase qty of existing line
    newLines[existingLineIndex] = {
      ...newLines[existingLineIndex],
      qty: newLines[existingLineIndex].qty + qty,
    };
  } else {
    // Add new line
    const newLine = {
      sku,
      name: product.name,
      qty,
      unitPrice: product.unitPrice,
      vatRate: product.vatRate,
    };

    if (discountPercent !== undefined) {
      newLine.discountPercent = discountPercent;
    }

    newLines.push(newLine);
  }

  const newInvoice = {
    ...invoice,
    lines: newLines,
  };

  return ok(newInvoice);
}

/**
 * Remove a line from an invoice.
 * @param {{ status: string, lines: Array<{ sku: string }> }} invoice
 * @param {string} sku
 * @returns {{ ok: true, value: object } | { ok: false, error: string }}
 */
export function removeLine(invoice, sku) {
  // Check invoice status
  if (invoice.status !== 'draft') {
    return fail('NOT_DRAFT');
  }

  // Check if line exists
  const lineIndex = invoice.lines.findIndex((line) => line.sku === sku);
  if (lineIndex === -1) {
    return fail('LINE_NOT_FOUND');
  }

  // Check if this is the last line
  if (invoice.lines.length === 1) {
    return fail('NO_LINES');
  }

  // Create new lines without the removed line
  const newLines = invoice.lines.filter((line) => line.sku !== sku).map((line) => ({ ...line }));

  const newInvoice = {
    ...invoice,
    lines: newLines,
  };

  return ok(newInvoice);
}

/**
 * Apply a voucher to an invoice.
 * @param {{ status: string, voucher?: object }} invoice
 * @param {{ code: string, amount: number }} voucher
 * @returns {{ ok: true, value: object } | { ok: false, error: string }}
 */
export function applyVoucher(invoice, { code, amount }) {
  // Check invoice status - must be draft
  if (invoice.status !== 'draft') {
    return fail('NOT_DRAFT');
  }

  // Check if voucher already exists
  if (invoice.voucher) {
    return fail('VOUCHER_EXISTS');
  }

  // Validate amount
  if (!Number.isInteger(amount) || amount <= 0) {
    return fail('AMOUNT_INVALID');
  }

  const newInvoice = {
    ...invoice,
    voucher: { code, amount },
  };

  return ok(newInvoice);
}

/**
 * Issue an invoice, assigning it a number and marking it as issued.
 * @param {{ status: string, issueDate: string }} invoice
 * @param {Array<string>} existingNumbers - Array of already-used invoice numbers
 * @returns {{ ok: true, value: object } | { ok: false, error: string }}
 */
export function issueInvoice(invoice, existingNumbers) {
  // Check invoice status
  if (invoice.status !== 'draft') {
    return fail('NOT_DRAFT');
  }

  // Generate next invoice number
  const number = nextInvoiceNumber(existingNumbers, invoice.issueDate);

  const issuedInvoice = {
    ...invoice,
    number,
    status: 'issued',
  };

  return ok(issuedInvoice);
}

